'use strict';
const $=id=>document.getElementById(id);
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const label=n=>String(n).padStart(3,'0');
let current=null,chosen=[],summary='';
const grid=$('numbers');
for(let n=1;n<=500;n++){const el=document.createElement('span');el.textContent=label(n);el.dataset.number=n;grid.append(el)}
function randomIndex(max){if(!globalThis.crypto?.getRandomValues)return Math.floor(Math.random()*max);const value=new Uint32Array(1),limit=Math.floor(4294967296/max)*max;do{crypto.getRandomValues(value)}while(value[0]>=limit);return value[0]%max}
function generate(){if(!current)return;const pool=Array.from({length:500},(_,i)=>i+1);for(let i=0;i<current.count;i++){const j=i+randomIndex(500-i);[pool[i],pool[j]]=[pool[j],pool[i]]}chosen=pool.slice(0,current.count).sort((a,b)=>a-b);$('assigned').replaceChildren(...chosen.map(n=>{const s=document.createElement('span');s.textContent=label(n);return s}));for(const el of grid.children)el.classList.toggle('selected',chosen.includes(Number(el.dataset.number)));$('number-help').textContent='Uma combinação de carinho para chamar de sua.';$('shuffle').disabled=false;$('total').textContent=money(current.price);$('summary-count').textContent=current.count===1?'1 número':`${current.count} números`;$('form-error').textContent=''}
document.querySelectorAll('.package').forEach(button=>button.addEventListener('click',()=>{current={count:Number(button.dataset.count),price:Number(button.dataset.price)};document.querySelectorAll('.package').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});generate()}));
$('shuffle').addEventListener('click',generate);
$('phone').addEventListener('input',e=>{const d=e.target.value.replace(/\D/g,'').slice(0,11);let v=d;if(d.length>2)v=`(${d.slice(0,2)}) ${d.slice(2)}`;if(d.length>6){const split=d.length>10?7:6;v=`(${d.slice(0,2)}) ${d.slice(2,split)}-${d.slice(split)}`}e.target.value=v});
$('form').addEventListener('submit',e=>{e.preventDefault();if(!current){$('form-error').textContent='Escolha um pacote solidário para continuar.';document.querySelector('.package').focus();return}const name=$('name').value.trim(),phone=$('phone').value,digits=phone.replace(/\D/g,'');if(name.length<2){$('form-error').textContent='Informe seu nome para continuar.';$('name').focus();return}if(digits.length<10||digits.length>11){$('form-error').textContent='Informe um WhatsApp com DDD válido.';$('phone').focus();return}$('form-error').textContent='';const rows=[['Nome',name],['WhatsApp',phone],['Pacote',`${current.count} número(s)`],['Números',chosen.map(label).join(' · ')],['Contribuição',money(current.price)]];$('preview-content').replaceChildren(...rows.map(([title,value])=>{const p=document.createElement('p'),strong=document.createElement('strong');strong.textContent=title+': ';p.append(strong,document.createTextNode(value));return p}));summary='PRÉVIA — Todos pelo Nicolau\n'+rows.map(([k,v])=>`${k}: ${v}`).join('\n')+'\nDemonstração: não é uma reserva válida. Nenhuma cobrança foi gerada.';$('copy-status').textContent='';$('preview').showModal()});
$('close-dialog').addEventListener('click',()=>$('preview').close());$('preview').addEventListener('click',e=>{if(e.target===$('preview')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
async function copyText(text){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return}const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok)throw new Error('copy')}
$('copy').addEventListener('click',async()=>{try{await copyText(summary);$('copy-status').textContent='Resumo copiado com carinho!'}catch{$('copy-status').textContent='Não foi possível copiar automaticamente. Selecione o resumo acima.'}});
$('share').addEventListener('click',async()=>{const data={title:'Todos pelo Nicolau',text:'Um número. Uma chance. Muito amor. Conheça a rifa solidária pelo Nicolau.',url:location.href.split('#')[0]};if(location.protocol==='file:'){$('share-status').textContent='O link de compartilhamento ficará disponível quando o site estiver online.';return}try{if(navigator.share){await navigator.share(data);$('share-status').textContent=''}else{await copyText(data.url);$('share-status').textContent='Link da campanha copiado!'}}catch(e){if(e.name!=='AbortError')$('share-status').textContent='Não foi possível compartilhar. Copie o endereço do navegador.'}});
